parameters.jsCode:
// Claude-built test data, synthetic. 10 copies each of E13 and E07, in the Gmail item shape
// "Sort and pull out" reads (date, from.text, subject, text). Used to count how often
// the extractor gives Low Priority, before and after the correction examples.
const emails = [
  {
    "id": "E07",
    "date": "2026-10-16T13:38:03.000Z",
    "from": {
      "text": "\"Jenna Mercer\" <crdemopersonas-jmercer@yahoo.com>"
    },
    "subject": "pink slips",
    "text": "Hi! It's Jenna (Ryan's wife). Can you email me the pink slips for both cars? I cleaned out the glovebox and I think I threw them out with the old receipts 🤦‍♀️\nThank you!!\n"
  },
  {
    "id": "E13",
    "date": "2026-10-19T14:12:00.000Z",
    "from": {
      "text": "\"Heather Gill\" <crdemopersonas-hgill@yahoo.com>"
    },
    "subject": "need a new pink slip",
    "text": "Hi,\n\nIs there any way you can send me another pink slip for the Tucson? I swapped purses this weekend and I have no idea where it went.\n\nThanks,\nHeather\n"
  }
];

const items = [];
for (const e of emails) {
  for (let i = 1; i <= 10; i++) {
    items.push({ json: { ...e, test_id: `${e.id}-${String(i).padStart(2, '0')}` } });
  }
}
return items;

